function mul32(a){var s=a>>>0;return function(){s=(s+0x6d2b79f5)>>>0;var e=s;
  e=Math.imul(e^e>>>15,1|e);e=(e+Math.imul(e^e>>>7,61|e))>>>0;
  return ((e^e>>>14)>>>0)/4294967296;};}
function peakData(seed,n,vary){var r=mul32(seed),l=vary/100,
  lo=K.heightNeutral-l*(K.heightNeutral-K.heightMinAtFullVary),
  hi=K.heightNeutral+l*(K.heightMaxAtFullVary-K.heightNeutral),o=[];
  for(var i=0;i<n;i++){var e=(2*r()-1)*l*K.widthVaryMax;
    o.push({h:lo+r()*(hi-lo),w:Math.max(.88,Math.min(1.12,1+e))});}
  return o;}

/* jedna náhodná matice na celou stopáž, ne nová každý snímek */
var RC={};
function rmat(cols,rows,seed){
  var key=cols+"_"+rows+"_"+seed,m=RC[key]; if(m) return m;
  var rnd=mul32(seed); m=[];
  for(var c=0;c<cols;c++){var col=new Float32Array(rows);
    for(var y=0;y<rows;y++) col[y]=rnd(); m.push(col);}
  RC[key]=m; return m;
}

/* geometrie vlny v jejich základních souřadnicích (šířka 1600) */
function makeWave(d,phase,amp,fadeMul){
  var base=K.baseWidth,c=.5*d,u=phase/100,m=peakData(SEED,PEAKS,VARY),r=K.gridSize;
  var mx=.01; for(var q=0;q<m.length;q++) mx=Math.max(mx,m[q].h);
  var p=Math.min((c-d*K.topMarginPct)/mx,(d-d*K.bottomMarginPct-c)/mx)*amp;
  var gb=Math.min(K.fadePct/100*d,2.2*Math.abs(p));
  var g=Math.max(gb,K.fadePct/100*d*.30)*(fadeMul||1),f=g/2;
  function wy(t){
    var rr=(t/base+u/PEAKS)*PEAKS,n=((Math.floor(rr)%PEAKS)+PEAKS)%PEAKS,
        li=rr-Math.floor(rr),i2=(n+1)%PEAKS,
        a=Math.max(0,Math.min(1,li)),s=a*a*(3-2*a),
        h=m[n].h*(1-s)+m[i2].h*s,dd=m[n].w*(1-s)+m[i2].w*s,xx=rr*Math.PI*2;
    return c-p*Math.sin(xx)*h*(1+(dd-1)*.35*(1-Math.pow(Math.cos(xx/2),2)));}
  return {wy:wy,c:c,p:p,g:g,f:f,r:r,base:base,d:d,
          cols:Math.floor(base/r),rows:Math.ceil(d/r)+1};
}

function drawWave(ctx,CW,CH,phase,thin,amp,paintBg,fadeMul){
  /* Jeden jediný způsob kreslení pro řídkou i plnou vlnu, ať mezi nimi není šev.
     Všechny body jdou do jedné cesty a kreslí se jedním fill(): překryvy se slijí,
     takže plná vlna vyjde jako souvislá plocha, přesně jako jejich bg-hero.webp. */
  var sc=CW/K.baseWidth,W=makeWave(CH/sc,phase,amp,fadeMul);
  var r=W.r,v=W.cols,k=W.rows;
  /* Bod na ditherovém okraji má u nich vždy 50 % buňky (naměřeno na bg-hero.webp:
     rozteč 16 px, bod 8 px). Hmota pod čárou je u nich plná. Aby mezi řídkou
     a plnou vlnou nebyl skok, roste velikost bodu v hmotě s hustotou: při řídké
     vlně je to jejich rastr oddělených čtverečků, při plné se body slijí do plochy. */
  var M=K.dotSizePct/100*r,j=(r-M)/2;
  var dens=Math.max(0,Math.min(1,(thin-.80)/.20));
  var Mm=(K.dotSizePct+62*dens)/100*r,jm=(r-Mm)/2;
  ctx.save(); ctx.scale(sc,sc);
  if(paintBg!==false){ctx.fillStyle=BG;ctx.fillRect(0,0,W.base,W.d);}
  var R=thin<.999?rmat(v+2,k+2,5):null,N=[];
  ctx.fillStyle=K.color;
  ctx.beginPath();
  for(var e1=0;e1<v;e1++){
    var t3=Math.round(W.wy(e1*r+r/2)/r);
    if(t3<0)t3=0; if(t3>k)t3=k; N[e1]=t3;
    var xx=e1*r+jm;
    for(var s2=t3;s2<=k;s2++){
      if(R&&R[e1][s2]>=thin) continue;
      ctx.rect(xx,s2*r+jm,Mm,Mm);
    }
  }
  ctx.fill();
  /* ditherový okraj: dokreslené body nad hranou a vykousnuté pod ní */
  var addX=[],addY=[],cutX=[],cutY=[];
  for(var e3=0;e3<v;e3++){
    var a3=W.wy(e3*r+r/2),
        n0=Math.max(0,Math.floor((a3-W.f)/r)-1),
        o1=Math.min(k-1,Math.ceil((a3+W.f)/r)+1),i3=N[e3];
    for(var s3=n0;s3<=o1;s3++){
      var nn=(s3*r+r/2-a3+W.f)/W.g; if(nn<=0||nn>=1) continue;
      var on=1/(1+Math.exp(-((nn-.5)*6)))>BAYER[((s3%8)+8)%8][((e3%8)+8)%8]/64;
      if(R&&R[e3][s3]>=thin) continue;
      if(s3<i3){ if(on){addX.push(e3*r+j);addY.push(s3*r+j);} }
      else { if(!on){cutX.push(e3*r+jm);cutY.push(s3*r+jm);} }
    }
  }
  if(addX.length){ctx.beginPath();
    for(var q1=0;q1<addX.length;q1++) ctx.rect(addX[q1],addY[q1],M,M);
    ctx.fillStyle=K.color; ctx.fill();}
  if(cutX.length){ctx.beginPath();
    for(var q2=0;q2<cutX.length;q2++) ctx.rect(cutX[q2],cutY[q2],Mm,Mm);
    ctx.fillStyle=BG; ctx.fill();}
  ctx.restore();
}

/* ── nájezd: modrá až k liště, jeden puntík, pole, vlna ─── */
function drawIntro(ctx,CW,CH,t,phase,bandFrac,ampT){
  var sc=CW/K.baseWidth,d=CH/sc,r=K.gridSize;
  var dB=d*bandFrac,off=d-dB;
  var W=makeWave(dB,phase,ampT,1);
  var cols=Math.floor(K.baseWidth/r),rows=Math.ceil(d/r)+1;
  var u=ease(ramp(t,.55,2.85)),z=Math.pow(900,1-u);
  /* 50 % je jejich rastr, 112 % je slitá hmota, na kterou pak naváže drawWave */
  var ratio=.50+(1.12-.50)*ease(ramp(t,2.6,4.6));
  /* střed kamery je geometrický střed plochy, aby při z=1 body padly
     přesně na mřížku, kterou kreslí drawWave */
  var M=r*ratio,cx=K.baseWidth/2,cy=d/2;
  ctx.save(); ctx.scale(sc,sc);
  ctx.fillStyle=BG; ctx.fillRect(0,0,K.baseWidth,d);
  ctx.fillStyle=K.color;
  var span=z>2?Math.ceil(Math.max(K.baseWidth,d)/(r*z))+2:1e9;
  var c0=Math.max(0,(cols>>1)-span),c1=Math.min(cols,(cols>>1)+span);
  var q0=Math.max(0,(rows>>1)-span),q1=Math.min(rows,(rows>>1)+span);
  /* rozpad: každá kostička má vlastní zpoždění, zrychlení a boční snos,
     takže se plocha rozsype na milion dílků směrem dolů a odkryje vlnu */
  var RS=rmat(cols+2,rows+2,9),sT=ease(ramp(t,2.85,5.15));
  for(var c=c0;c<=c1;c++){
    var topR=Math.round((off+W.wy(c*r+r/2))/r); if(topR<0) topR=0;
    for(var q=q0;q<=q1;q++){
      var gx=c*r+r/2,gy=q*r+r/2,al=1;
      if(sT>0&&q<topR){
        var rv=RS[c<0?0:c][q<0?0:q],dl=rv*.46;
        var pr=ease(Math.max(0,Math.min(1,(sT-dl)/(1-dl))));
        if(pr>=.99) continue;
        var dist=(topR-q)*r;
        gy+=dist*pr+pr*pr*d*.62;
        gx+=(RS[(c*13+7)%cols][q<0?0:q]-.5)*r*14*pr;
        al=1-pr*pr;
      }
      if(al<=.03) continue;
      var px=cx+(gx-cx)*z,py=cy+(gy-cy)*z,sz=M*z;
      if(px+sz/2<0||px-sz/2>K.baseWidth||py+sz/2<0||py-sz/2>d) continue;
      ctx.globalAlpha=al; ctx.fillRect(px-sz/2,py-sz/2,sz,sz);
    }
  }
  ctx.globalAlpha=1; ctx.restore();
}


